using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class OptimizeReportMeshes {public static string Main(){var paths=AssetDatabase.GetDependencies(new[]{"Assets/Scenes/MountainLoop.unity","Assets/Scenes/MountainLoopReverse.unity"},true).Where(p=>p.StartsWith("Assets/Track/ReportCleanup/")&&p.EndsWith(".asset")).ToArray();var notes=new List<string>();foreach(var path in paths){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!mesh||mesh.vertexCount<100000)continue;var old=mesh.vertices;var oldColors=mesh.colors;var oldUv=mesh.uv;var vertices=new List<Vector3>();var colors=new List<Color>();var uv=new List<Vector2>();var lookup=new Dictionary<(Vector3Int,Color,Vector2),int>();var remap=new int[old.Length];for(int i=0;i<old.Length;i++){Color c=oldColors.Length==old.Length?oldColors[i]:Color.white;Vector2 u=oldUv.Length==old.Length?oldUv[i]:Vector2.zero;var key=(Vector3Int.RoundToInt(old[i]*10000),c,u);if(!lookup.TryGetValue(key,out var index)){index=vertices.Count;lookup[key]=index;vertices.Add(old[i]);colors.Add(c);uv.Add(u);}remap[i]=index;}if(vertices.Count==old.Length)continue;var triangles=mesh.triangles.Select(i=>remap[i]).ToArray();mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(vertices);mesh.SetColors(colors);if(oldUv.Length==old.Length)mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);notes.Add(path+": "+old.Length+" -> "+vertices.Count+" vertices; triangle positions unchanged to 0.1mm");}AssetDatabase.SaveAssets();File.WriteAllLines("Docs/ReportCleanup/mesh-storage.txt",notes);return "Compacted "+notes.Count+" referenced authored meshes";}}
